const input = $input.first().json;
const body = input.body || input;

const toko = String(body.target_toko || 'KUNCI SUKSES, TOKO').trim().toUpperCase();
const pof = String(body.target_pof || 'DIAN').trim().toUpperCase();
const rawSeris = Array.isArray(body.bundle_seris)
  ? body.bundle_seris
  : String(body.bundle_seris || 'DIEGO,GRANIT').split(',');

const cleanSeris = rawSeris.map(s => String(s).trim().toUpperCase()).filter(Boolean);
const qty = Math.max(1, Number(body.qty_per_item) || 60);
const repeat = Math.min(20, Math.max(1, Number(body.repeat_baskets) || 1));

return [{
  json: {
    target_toko: toko,
    target_pof: pof,
    bundle_seris: cleanSeris.length ? cleanSeris : ['DIEGO', 'GRANIT'],
    qty_per_item: qty,
    repeat_baskets: repeat,
    auto_remine: true
  }
}];

const res = $input.first().json;
const remine = res.remine || res.meta || {};
const top = (res.top_rules_after || res.top_rules || []).slice(0, 5).map(r => ({
  rule: `${r.antecedents_str} -> ${r.consequents_str}`,
  confidence_pct: Number((r.confidence * 100).toFixed(2)),
  lift: Number(r.lift.toFixed(3)),
  zhang: Number(r.zhang_metric.toFixed(3)),
  avg_dus: Number(r.avg_qty_dus.toFixed(1)),
  p_fisher: r.p_value_fisher
}));

return [{
  json: {
    pipeline: 'n8n -> FastAPI -> Supabase',
    status: 'synced',
    batch_tag: res.batch_tag || 'cron_audit',
    inserted_transactions: res.inserted_transactions || 0,
    total_baskets: remine.total_baskets || 0,
    rules_found: remine.rules_found || 0,
    significant_rules: remine.significant_rules || 0,
    exec_time_ms: remine.exec_time_ms || 0,
    top_5_significant_rules: top,
    timestamp: new Date().toISOString()
  }
}];
